begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('b9500000-0000-4000-8000-000000000001','bill-owner@example.invalid'),('b9500000-0000-4000-8000-000000000002','bill-member@example.invalid');
insert into public.organizations(id,name,slug) values('b9500000-0000-4000-8000-000000000010','Matching','bill-match'),('b9500000-0000-4000-8000-000000000011','Other matching','other-bill-match');
insert into public.memberships(org_id,user_id,role) values('b9500000-0000-4000-8000-000000000010','b9500000-0000-4000-8000-000000000001','owner'),('b9500000-0000-4000-8000-000000000010','b9500000-0000-4000-8000-000000000002','member');
insert into public.vendors(id,org_id,name,payment_terms_days) values('b9500000-0000-4000-8000-000000000020','b9500000-0000-4000-8000-000000000010','Supplier',14),('b9500000-0000-4000-8000-000000000021','b9500000-0000-4000-8000-000000000010','Second supplier',30);
insert into public.purchase_orders(id,org_id,number,vendor_id,status) select ('b9500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b9500000-0000-4000-8000-000000000010','MATCH-'||n,case when n=54 then 'b9500000-0000-4000-8000-000000000021'::uuid else 'b9500000-0000-4000-8000-000000000020'::uuid end,'received' from generate_series(50,57) n;
insert into public.purchase_order_items(id,org_id,purchase_order_id,description,quantity,received_quantity,unit_cost_satang) select ('b9500000-0000-4000-8000-'||lpad((n+100)::text,12,'0'))::uuid,'b9500000-0000-4000-8000-000000000010',('b9500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Matched service',10,10,100 from generate_series(50,57) n;
create function pg_temp.bill(n integer,ref text,patch jsonb default '{}') returns uuid language sql as $$select public.bill_purchase_order('b9500000-0000-4000-8000-000000000010',('b9500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,jsonb_build_object('vendor_reference',ref,'bill_date','2026-10-01','input_vat_rate',7,'input_vat_satang',70,'vendor_total_satang',1070)||patch)$$;
insert into public.vendors(id,org_id,name) values('b9500000-0000-4000-8000-000000000022','b9500000-0000-4000-8000-000000000011','Foreign supplier');
insert into public.purchase_orders(id,org_id,number,vendor_id) values('b9500000-0000-4000-8000-000000000058','b9500000-0000-4000-8000-000000000011','FOREIGN-1','b9500000-0000-4000-8000-000000000022');
insert into public.vendor_bill_matches(org_id,vendor_id,purchase_order_id,vendor_reference,kind,bill_date,due_date,tolerance_bps) values('b9500000-0000-4000-8000-000000000011','b9500000-0000-4000-8000-000000000022','b9500000-0000-4000-8000-000000000058','FOREIGN-BILL','bill','2026-10-01','2026-10-31',100);
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.vendor_bill_matches'::regclass),'matching evidence forces RLS');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b9500000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select set_config('test.matched',pg_temp.bill(50,' INV-001 ')::text,true);
select is((select vendor_invoice_reference from public.costs where id=current_setting('test.matched')::uuid),'INV-001','vendor reference retained');
select is((select amount_satang from public.costs where id=current_setting('test.matched')::uuid),1070::bigint,'vendor gross total is money out');
select is((select input_vat_satang from public.costs where id=current_setting('test.matched')::uuid),70::bigint,'input VAT stored separately');
select is((select due_date from public.costs where id=current_setting('test.matched')::uuid),'2026-10-15'::date,'terms applied from vendor invoice date');
select throws_ok($$select pg_temp.bill(51,'inv-001')$$,'P0001','Duplicate vendor invoice reference','reference uniqueness ignores case and whitespace');
select throws_ok($$select pg_temp.bill(50,'INV-001')$$,'P0001','Duplicate vendor invoice reference','retry refuses duplicate reference');
select throws_ok($$select pg_temp.bill(51,'PRICE','{"lines":[{"id":"b9500000-0000-4000-8000-000000000151","quantity":10,"expected_quantity":10,"unit_cost_satang":102}],"input_vat_satang":71,"vendor_total_satang":1091}')$$,'P0001','Variance reason required','price above tolerance requires reason');
select lives_ok($$select pg_temp.bill(51,'PRICE','{"lines":[{"id":"b9500000-0000-4000-8000-000000000151","quantity":10,"expected_quantity":10,"unit_cost_satang":102}],"input_vat_satang":71,"vendor_total_satang":1091,"variance_reason":"Supplier price approved"}')$$,'reason accepts price variance');
select is((select variance_reason from public.vendor_bill_matches where vendor_reference='PRICE'),'Supplier price approved','reason is immutable evidence');
select throws_ok($$select pg_temp.bill(52,'QTY','{"lines":[{"id":"b9500000-0000-4000-8000-000000000152","quantity":11,"expected_quantity":10,"unit_cost_satang":100}],"input_vat_satang":77,"vendor_total_satang":1177}')$$,'P0001','Variance reason required','quantity variance requires reason');
select lives_ok($$select pg_temp.bill(52,'QTY','{"lines":[{"id":"b9500000-0000-4000-8000-000000000152","quantity":11,"expected_quantity":10,"unit_cost_satang":100}],"input_vat_satang":77,"vendor_total_satang":1177,"variance_reason":"Supplier quantity accepted"}')$$,'accept quantity with reason and preserve receipt accounting');
select is((select billed_quantity from public.purchase_order_items where id='b9500000-0000-4000-8000-000000000152'),10::numeric,'matching consumes actual received baseline');
select throws_ok($$select pg_temp.bill(53,'VAT','{"input_vat_satang":69,"vendor_total_satang":1069}')$$,'P0001','Variance reason required','manual VAT discrepancy requires reason');
select throws_ok($$select pg_temp.bill(53,'TOTAL','{"vendor_total_satang":1071}')$$,'P0001','Variance reason required','total discrepancy requires reason');
select lives_ok($$select pg_temp.bill(54,'inv-001')$$,'same reference is allowed for another vendor');
select throws_ok($$select pg_temp.bill(55,'STALE','{"lines":[{"id":"b9500000-0000-4000-8000-000000000155","quantity":10,"expected_quantity":9,"unit_cost_satang":100}]}')$$,'P0001','Receipt changed, reload','stale receipt rejected');
select throws_ok($$select pg_temp.bill(55,'BAD','{"input_vat_satang":-1}')$$,'P0001','Valid vendor reference, dates, VAT and total required','negative VAT rejected');
select throws_ok($$select pg_temp.bill(55,'BAD','{"due_date":"2026-09-01"}')$$,'P0001','Due date must be on or after bill date','backward due date rejected');
select throws_ok($$update public.costs set input_vat_satang=0 where id=current_setting('test.matched')::uuid$$,'P0001','Vendor bill evidence is immutable','VAT cannot be altered directly');
select throws_ok($$insert into public.costs(org_id,amount_satang,input_vat_satang) values('b9500000-0000-4000-8000-000000000010',100,7)$$,'P0001','Use purchase billing command','manual cost cannot forge input VAT');
select throws_ok($$select public.bill_purchase_order('b9500000-0000-4000-8000-000000000011','b9500000-0000-4000-8000-000000000058','{}')$$,'P0001','Only owners and admins may manage purchases','cross tenant matching command refused');
select throws_ok($$update public.vendor_bill_matches set vendor_reference='changed'$$,'42501',null,'match evidence cannot be edited');
select lives_ok($$select public.return_purchase_order('b9500000-0000-4000-8000-000000000010','b9500000-0000-4000-8000-000000000050','[{"id":"b9500000-0000-4000-8000-000000000150","returned_quantity":1}]')$$,'return creates negative cost');
select set_config('test.credit',(select id::text from public.costs where purchase_order_id='b9500000-0000-4000-8000-000000000050' and purchase_cost_kind='credit'),true);
select throws_ok($$select public.link_vendor_credit('b9500000-0000-4000-8000-000000000010',current_setting('test.credit')::uuid,jsonb_build_object('vendor_reference','CN-OVER','bill_date','2026-10-10','input_vat_rate',7,'input_vat_satang',71,'variance_reason','Requested excess VAT','original_bill_id',(select vendor_bill_match_id from public.costs where id=current_setting('test.matched')::uuid)))$$,'P0001','Credit VAT exceeds remaining original input VAT','credit cannot reverse more input VAT than original invoice');
select lives_ok($$select public.link_vendor_credit('b9500000-0000-4000-8000-000000000010',current_setting('test.credit')::uuid,jsonb_build_object('vendor_reference','CN-001','bill_date','2026-10-10','input_vat_rate',7,'input_vat_satang',7,'original_bill_id',(select vendor_bill_match_id from public.costs where id=current_setting('test.matched')::uuid)))$$,'negative return cost links vendor credit reference');
select is((select amount_satang from public.costs where id=current_setting('test.credit')::uuid),-107::bigint,'credit reverses gross money out');
select is((select input_vat_satang from public.costs where id=current_setting('test.credit')::uuid),-7::bigint,'credit reverses input VAT');
select is((select input_vat_satang from public.monthly_purchase_vat where month='2026-10-01'),281::bigint,'monthly input VAT nets linked credits');
select throws_ok($$select public.link_vendor_credit('b9500000-0000-4000-8000-000000000010',current_setting('test.credit')::uuid,'{}')$$,'P0001','Vendor credit already linked','cannot apply credit VAT twice');
reset role;
insert into public.org_settings(org_id,bill_variance_tolerance_bps) values('b9500000-0000-4000-8000-000000000010',500) on conflict(org_id) do update set bill_variance_tolerance_bps=500;
set local role authenticated;
select lives_ok($$select pg_temp.bill(56,'TOLERANCE','{"lines":[{"id":"b9500000-0000-4000-8000-000000000156","quantity":10,"expected_quantity":10,"unit_cost_satang":105}],"input_vat_satang":74,"vendor_total_satang":1124}')$$,'org tolerance permits the exact boundary');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b9500000-0000-4000-8000-000000000002"}',true);
update public.org_settings set bill_variance_tolerance_bps=10000 where org_id='b9500000-0000-4000-8000-000000000010';
select is((select bill_variance_tolerance_bps from public.org_settings where org_id='b9500000-0000-4000-8000-000000000010'),500,'member cannot weaken matching policy');
select throws_ok($$select pg_temp.bill(57,'MEMBER')$$,'P0001','Only owners and admins may manage purchases','member cannot match invoices');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b9500000-0000-4000-8000-000000000001"}',true);
select is((select count(*)::int from public.vendor_bill_matches where org_id='b9500000-0000-4000-8000-000000000011'),0,'foreign tenant evidence hidden');
reset role;
insert into public.products(id,org_id,name,is_stockable) values('b9500000-0000-4000-8000-000000000030','b9500000-0000-4000-8000-000000000010','Matched stock',true);
insert into public.purchase_order_items(org_id,purchase_order_id,product_id,description,quantity,received_quantity,unit,unit_cost_satang) values('b9500000-0000-4000-8000-000000000010','b9500000-0000-4000-8000-000000000057','b9500000-0000-4000-8000-000000000030','Mixed stock',1,1,'piece',1);
set local role authenticated;
select lives_ok($$select pg_temp.bill(57,'MIXED','{"vendor_total_satang":1071}')$$,'one invoice matches mixed inventory and service');
select is((select count(*)::int from public.costs where vendor_invoice_reference='MIXED'),2,'mixed bill keeps two cost categories');
select is((select count(distinct vendor_bill_match_id)::int from public.costs where vendor_invoice_reference='MIXED'),1,'mixed costs share one unique vendor invoice');
select is((select sum(input_vat_satang)::bigint from public.costs where vendor_invoice_reference='MIXED'),70::bigint,'VAT allocated once across mixed categories');
select is((select sum(amount_satang)::bigint from public.costs where vendor_invoice_reference='MIXED'),1071::bigint,'mixed money out equals vendor total');
select is((select sum(amount_satang)::bigint from public.costs where vendor_invoice_reference='MIXED' and category='inventory'),1::bigint,'stock amount keeps inventory exclusion');
select lives_ok($$select public.update_finance_lock_date('b9500000-0000-4000-8000-000000000010','2026-09-30')$$,'set closed financial period');
select throws_ok($$select pg_temp.bill(55,'LOCKED','{"bill_date":"2026-09-30"}')$$,'P0001','Finance period is locked','matched vendor bill respects finance lock');
reset role;
select throws_ok($$insert into public.vendor_bill_matches(org_id,vendor_id,purchase_order_id,vendor_reference,kind,bill_date,due_date,tolerance_bps) values('b9500000-0000-4000-8000-000000000010','b9500000-0000-4000-8000-000000000020','b9500000-0000-4000-8000-000000000055',' mixed ','bill','2026-10-01','2026-10-15',100)$$,'23505',null,'unique index enforces duplicate reference independently of command');
select * from finish();
rollback;
